<template>
  <div :class="cn('flex flex-col gap-1.5 w-full')">
    <p v-if="label" class="text-sm font-medium">{{ label }}</p>
    <Select class="border-border" :model-value="value" @update:model-value="onChange">
      <SelectTrigger class="gap-2 shadow-sm" :is-loading="isLoading" :icon="icon">
        <SelectValue class="text-foreground-muted" :placeholder="placeholder">
          {{ selectedItem ? `${selectedItem.name ?? selectedItem.value}` : placeholder }}
        </SelectValue>
      </SelectTrigger>
      <SelectContent>
        <p v-if="!items.length" class="p-4 text-sm text-accent-foreground select-none">No items to select</p>
        <SelectItem
          v-for="(item, index) in allItems"
          v-else
          :key="item.value || index"
          :value="item.value"
          :disabled="item?.disabled"
        >
          {{ item.name ?? item.value }}
        </SelectItem>
      </SelectContent>
    </Select>
    <p v-if="errorMessage && !isOffline" class="p-2 text-sm text-destructive select-none">{{ errorMessage }}</p>
  </div>
</template>

<script setup lang="ts" generic="T extends string">
import type { AcceptableValue } from 'reka-ui';
import { cn } from '@/lib/utils';

import { getErrorMessage } from '~/utils/getErrorMessage';

const { isOffline } = useNetworkStatus();

interface Props {
  label?: string;
  items: SelectItem<T>[];
  value: T | null;
  placeholder?: string;
  propertyName: string;
  isLoading?: boolean;
  error?: string;
  nullIsAll: boolean;
  changePage?: boolean;
  icon?: any;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: 'Select an option',
  isLoading: false,
  error: undefined,
  label: undefined,
  changePage: true,
  icon: undefined,
});
const errorMessage = computed(() => getErrorMessage(props.error));

const route = useRoute();

const allItems = computed(() => {
  if (props.nullIsAll) {
    return [{ name: props.placeholder, value: null }, ...props.items];
  }
  return props.items;
});
const selectedItem = computed(() => {
  return allItems.value.find((item) => item.value === props.value) ?? null;
});

async function onChange(value: AcceptableValue) {
  value = value as T | null;
  const propertyNames = props.propertyName.split('|');
  const propertyValues = value?.split('|') || [];
  const propertyObject: Record<string, string | undefined> = {};
  propertyNames.forEach((name, index) => {
    propertyObject[name] = propertyValues[index] || undefined;
  });
  await navigateTo({
    name: route.name,
    params: route.params,
    query: {
      ...route.query,
      ...(props.changePage && { page: 1 }),
      ...propertyObject,
    },
  });
}
</script>
